// Gerado a partir da assinatura monocromatica oficial da pagina 9 de
// docs/key-visual/Grazing Table and Co - Logos and Patterns.pdf.
type LogoZpl = { largura: number; altura: number; bytesPorLinha: number; hexadecimal: string };

const LOGOS: Record<string, LogoZpl> = {
  "203-compacta": { largura: 96, altura: 95, bytesPorLinha: 12, hexadecimal: "" },
  "300-compacta": { largura: 142, altura: 140, bytesPorLinha: 18, hexadecimal: "" },
  "600-compacta": { largura: 283, altura: 280, bytesPorLinha: 36, hexadecimal: "" },
  "203-padrao": { largura: 120, altura: 119, bytesPorLinha: 15, hexadecimal: "" },
  "300-padrao": { largura: 177, altura: 175, bytesPorLinha: 23, hexadecimal: "" },
  "600-padrao": { largura: 354, altura: 350, bytesPorLinha: 45, hexadecimal: "" },
};

export function logoGrazingZpl(resolucaoDpi: number, compacta: boolean): LogoZpl {
  const dpi = [203, 300, 600].reduce((anterior, atual) =>
    Math.abs(atual - resolucaoDpi) < Math.abs(anterior - resolucaoDpi) ? atual : anterior,
  );
  return LOGOS[`${dpi}-${compacta ? 'compacta' : 'padrao'}`];
}
